// app/login/hero-photo.js — the brand-pane photograph, inlined.
//
// Deliberately a base64 data URI rather than a file in public/: the sign-in
// design was supplied with the image embedded, and it is reproduced as given.
// It costs ~332 KB of prerendered HTML on /login and cannot be cached
// separately from the document, which is the accepted trade for matching the
// design exactly. The same photograph is credited on /credits.
//
// Imported only by the server component (app/login/page.jsx). Importing it
// from the client form would ship the whole string a second time inside the
// JS bundle, doubling the cost for no benefit.
export const HERO_PHOTO =
  "data:image/jpeg;base64,";
